import logging


class Logger(object):

    DEFAULT_FORMATTER = '%(asctime)s - %(name)s - %(levelname)s - %(message)s'
    logging_level = {
                        'info': logging.INFO,
                        'debug': logging.DEBUG,
                        'warning': logging.WARNING,
                        'error': logging.ERROR,
                        'critical': logging.CRITICAL
                    }

    def __init__(self, logger_name, console_log=False, file_log_name=''):
        self._logger_name = logger_name

        self._console_log = console_log
        self._console_level = 'info'
        self._console_formatter = Logger.DEFAULT_FORMATTER
        self._console_handler = None

        self._file_name = file_log_name
        self._file_level = 'debug'
        self._file_formatter = Logger.DEFAULT_FORMATTER
        self._file_handler = None

        self.logger = logging.getLogger(logger_name)
        self.logger.setLevel(logging.DEBUG)

        self._add_console_handlers(console_log)
        self._add_file_handlers(file_log_name)

    def _remove_console_handlers(self):
        if self._console_handler:
            self.logger.removeHandler(self._console_handler)
            self._console_handler = None

    def _remove_file_handlers(self):
        if self._file_handler:
            self.logger.removeHandler(self._file_handler)
            self._file_handler = None

    def _add_console_handlers(self, console_log=False, level='info', formatter=DEFAULT_FORMATTER):
        self._console_log = console_log
        self._console_level = level
        self._console_formatter = formatter

        formatter = logging.Formatter(formatter)
        if console_log:
            self._console_handler = logging.StreamHandler()
            log_level = Logger.logging_level[level.lower()]
            self._console_handler.setLevel(log_level)
            self._console_handler.setFormatter(formatter)
            self.logger.addHandler(self._console_handler)

    def _add_file_handlers(self, file_log_name='', level='debug', formatter=DEFAULT_FORMATTER):
        self._file_name = file_log_name
        self._file_level = level
        self._file_formatter = formatter

        formatter = logging.Formatter(formatter)
        if file_log_name:
            self._file_handler = logging.FileHandler(file_log_name)
            log_level = Logger.logging_level[level.lower()]
            self._file_handler.setLevel(log_level)
            self._file_handler.setFormatter(formatter)
            self.logger.addHandler(self._file_handler)
